Method.Implementation:
  #DIM status AS %Status
  set status = $$$OK
  try{
   set uuepdf = pRequest.StringValue
   Set tSC = ..GetConnection(.tJavaGateway)
   If $$$ISOK(tSC){
     $$$TRACE("Here to do UUDecode...")
     set PDFUUDecoder = ##class(com.ihc.itf.util.IHCUUDecoder).%New(tJavaGateway)
	 set pResponse=##class(Ens.StringResponse).%New()
	 set pResponse.StringValue=""
	 set uupdf = PDFUUDecoder.decode(uuepdf)
	 If '$IsObject(uupdf){
	   $$$TRACE(">>>>>uupf is not an object")
       Set sc = $System.Status.Error($$$GeneralError,"UUDecoder returned a null reference")
       Quit
     }
     Set tcharStream = ##class(%GlobalCharacterStream).%New()
     Set tStatus = tcharStream.CopyFrom(uupdf)
     $$$TRACE("tcharStream size:"_tcharStream.Size)
     set text=""
     While 'tcharStream.AtEnd {
       Set text = text_tcharStream.Read($$$MaxStringLength)
     } 
     set pResponse.StringValue=text
	 Kill tcharStream
     Kill uupdf
     Kill tJavaGateway
   }	
  }catch err{
	$$$TRACE("Exception Calling UUDecoder: " _ err)
	set status = $$$ERROR("Exception in UUDecode Operation")
  }

  return status
